class AeroDataBoxClient(private val apiKey: String) {

    companion object {
        private const val HOST = "aerodatabox.p.rapidapi.com"
        private const val BASE = "https://aerodatabox.p.rapidapi.com"
        private const val IATA = "RUH"
        private const val MAX_WINDOW_HOURS = 11
    }

    fun fetchDayCounts(date: LocalDate): Counts {
        val dayStart = date.atStartOfDay(TimeFmt.riyahdhSafe())
        val nowLdt = LocalDateTime.now(TimeFmt.riyahdhSafe())
        val dayEnd = date.atTime(23, 59)
        val effectiveEnd = if (date == TimeFmt.today()) nowLdt else dayEnd

        if (!effectiveEnd.isAfter(dayStart)) return Counts(0, 0)

        var cursor = dayStart
        var arrived = 0
        var departed = 0

        while (cursor.isBefore(effectiveEnd)) {
            val windowEnd = cursor.plusHours(MAX_WINDOW_HOURS.toLong()).let {
                if (it.isAfter(effectiveEnd)) effectiveEnd else it
            }
            val flights = fetchWindow(cursor, windowEnd)
            for (f in flights) {
                if (f.cancelled) continue
                val dir = f.direction?.lowercase() ?: continue
                val hasActual = hasRealMovement(f)
                if (!hasActual) continue
                when (dir) {
                    "arrival" -> arrived++
                    "departure" -> departed++
                }
            }
            cursor = windowEnd
        }

        return Counts(arrived, departed)
    }

    private fun hasRealMovement(f: ApiFlight): Boolean {
        if (TimeFmt.parseUtc(f.runwayUtc) != null) return true
        if (TimeFmt.parseUtc(f.actualUtc) != null) return true
        val rev = TimeFmt.parseUtc(f.revisedUtc) ?: return false
        val sched = TimeFmt.parseUtc(f.scheduledUtc)
        val liveMarkers = setOf(
            "liveupdates", "adsbdata", "flightscheduleslive",
            "live", "adsb", "actual", "runway"
        )
        val qLive = f.quality.any { q ->
            val n = q.lowercase().replace(Regex("[^a-z]"), "")
            liveMarkers.any { n.contains(it) }
        }
        if (qLive) return true
        if (sched != null && rev != sched) return true
        return false
    }

    private fun fetchWindow(startLdt: LocalDateTime, endLdt: LocalDateTime): List<ApiFlight> {
        val from = TimeFmt.localPath(startLdt.atZone(TimeFmt.riyahdhSafe()).toInstant())
        val to = TimeFmt.localPath(endLdt.atZone(TimeFmt.riyahdhSafe()).toInstant())
        val qs = buildString {
            append("withLeg=false")
            append("&direction=Both")
            append("&withCancelled=false")
            append("&withCodeshared=false")
            append("&withCargo=false")
            append("&withPrivate=false")
        }
        val urlStr = "$BASE/flights/airports/iata/$IATA/${enc(from)}/${enc(to)}?$qs"
        val body = get(urlStr)
        return parseFlights(body)
    }

    private fun enc(s: String) = URLEncoder.encode(s, "UTF-8")

    private fun get(urlStr: String): String {
        val conn = URL(urlStr).openConnection() as HttpURLConnection
        try {
            conn.requestMethod = "GET"
            conn.connectTimeout = 25000
            conn.readTimeout = 25000
            conn.setRequestProperty("X-RapidAPI-Key", apiKey)
            conn.setRequestProperty("X-RapidAPI-Host", HOST)
            conn.setRequestProperty("Accept", "application/json")

            val code = conn.responseCode
            if (code !in 200..299) {
                val err = conn.errorStream?.bufferedReader()?.use(BufferedReader::readText) ?: ""
