                    obj.has("results") -> obj.getJSONArray("results")
                    else -> JSONArray()
                }
            }
            else -> return emptyList()
        }
        val out = ArrayList<ApiFlight>(arr.length())
        for (i in 0 until arr.length()) {
            val o = arr.optJSONObject(i) ?: continue
            val mv = o.optJSONObject("movement") ?: o.optJSONObject("arrival") ?: o.optJSONObject("departure")
            val dir = o.optString("direction").ifBlank {
                when {
                    o.has("arrival") && !o.has("departure") -> "Arrival"
                    o.has("departure") && !o.has("arrival") -> "Departure"
                    else -> ""
                }
            }
            val quality = ArrayList<String>()
            val qArr = mv?.optJSONArray("quality")
            if (qArr != null) {
                for (j in 0 until qArr.length()) quality.add(qArr.optString(j))
            }
            out.add(
                ApiFlight(
                    direction = dir,
                    runwayUtc = extractUtc(mv, "runwayTime") ?: extractUtc(mv, "actualRunway"),
                    revisedUtc = extractUtc(mv, "revisedTime") ?: extractUtc(mv, "estimatedTime"),
                    actualUtc = extractUtc(mv, "actualTime") ?: mv?.optString("actualTimeUtc")?.takeIf { it.isNotBlank() },
                    scheduledUtc = extractUtc(mv, "scheduledTime"),
                    quality = quality,
                    cancelled = mv?.optBoolean("cancelled", false) ?: o.optBoolean("cancelled", false)
                )
            )
        }
        return out
    }

    private fun extractUtc(mv: JSONObject?, key: String): String? {
        if (mv == null) return null
        val node = mv.optJSONObject(key) ?: return mv.optString(key).takeIf { it.isNotBlank() }
        val utc = node.optString("utc").ifBlank { node.optString("Utc") }
        return utc.takeIf { it.isNotBlank() }
    }
