                        ?: mv?.optString("actualTimeUtc")?.takeIf { it.isNotBlank() },
                    scheduledUtc = extractUtc(mv, "scheduledTime"),
                    quality = quality,
                    cancelled = mv?.optBoolean("cancelled", false) ?: o.optBoolean("cancelled", false)
                )
            )
        }
        return out
    }

    private fun extractUtc(mv: JSONObject?, key: String): String? {
        if (mv == null) return null
        val node = mv.optJSONObject(key)
        if (node != null) {
            val utc = node.optString("utc").ifBlank { node.optString("Utc") }
            if (utc.isNotBlank()) return utc
        }
        val flat = mv.optString(key)
        return flat.takeIf { it.isNotBlank() }
    }
}

