                    showCached()
                    return@launch
                }

                val c = counts ?: Counts(0, 0)
                val prev = store.getDays()[todayKey]
                if (prev != null && c.arrived > prev.arrived) {
                    notifier.arrivalsIncreased(c.arrived, prev.arrived)
                }
                store.saveDay(
                    DayStat(
                        date = todayKey,
                        arrived = c.arrived,
                        departed = c.departed,
                        updatedAtIso = Instant.now().toString(),
                        lastFetchOk = true,
                        errorMsg = null
                    )
                )
                for ((k, bc) in backfilled) {
                    store.saveDay(
                        DayStat(
                            date = k,
                            arrived = bc.arrived,
                            departed = bc.departed,
                            updatedAtIso = Instant.now().toString(),
                            lastFetchOk = true,
                            errorMsg = null
                        )
                    )
                }

