import android.content.Context
import android.content.SharedPreferences

data class Quota(
    val limit: Int?,
    val remaining: Int?,
    val resetAtIso: String?,
    val selfUsed: Int,
    val selfLimit: Int,
    val monthKey: String
)

class QuotaStore(context: Context) {

    private val prefs: SharedPreferences =
        context.getSharedPreferences("ruh_quota", Context.MODE_PRIVATE)

    companion object {
        const val FREE_LIMIT = 500
    }

    private fun currentMonth(): String =
        TimeFmt.today().toString().substring(0, 7)

    fun recordCall(): Int {
        val month = currentMonth()
        var used = if (prefs.getString("month", "") == month) prefs.getInt("used", 0) else 0
        used++
        prefs.edit()
            .putString("month", month)
            .putInt("used", used)
            .apply()
        return used
    }

    fun recordHeaders(headers: Map<String, String>) {
        val lower = headers.mapKeys { it.key.lowercase() }
        val limit = (lower["x-ratelimit-limit"] ?: lower["x-rapidapi-limit"]
            ?: lower["x-ratelimit-max"])?.toIntOrNull()
        val remaining = (lower["x-ratelimit-remaining"] ?: lower["x-rapidapi-remaining"]
            ?: lower["x-ratelimit-left"])?.toIntOrNull()
        val reset = lower["x-ratelimit-reset"] ?: lower["x-rapidapi-reset"]

        val editor = prefs.edit()
        if (limit != null) editor.putInt("h_limit", limit)
        if (remaining != null) editor.putInt("h_remaining", remaining)
        if (reset != null) editor.putString("h_reset", reset)
        editor.apply()
    }

    fun get(): Quota {
        val month = currentMonth()
        val used = if (prefs.getString("month", "") == month) prefs.getInt("used", 0) else 0
        val hLimit = if (prefs.contains("h_limit")) prefs.getInt("h_limit", -1) else null
        val hRemaining = if (prefs.contains("h_remaining")) prefs.getInt("h_remaining", -1) else null
        val hReset = prefs.getString("h_reset", null)
        return Quota(
            limit = hLimit?.takeIf { it > 0 },
            remaining = hRemaining?.takeIf { it >= 0 },
            resetAtIso = hReset,
            selfUsed = used,
            selfLimit = FREE_LIMIT,
            monthKey = month
        )
    }

    fun displayLine(): String {
        val q = get()
        val limit = q.limit ?: q.selfLimit
        val remaining = q.remaining ?: (limit - q.selfUsed).coerceAtLeast(0)
        val used = limit - remaining
        return "API quota: $remaining of $limit left this month (used $used)"
    }
