{"type":"tool","tool":"edit","callID":"call_03f8acb640ec48989728058b","state":{"status":"completed","input":{"filePath":"/data/data/com.termux/files/home/ruh-counter/app/src/main/java/com/ruh/counter/ApiClient.kt","newString":"    private fun parseFlights(json: String): List<ApiFlight> {
        val trimmed = json.trim()
        if (trimmed.isEmpty() || trimmed == "null") return emptyList()
        val out = ArrayList<ApiFlight>()

        if (trimmed.startsWith("[")) {
            val arr = JSONArray(trimmed)
            for (i in 0 until arr.length()) {
                val o = arr.optJSONObject(i) ?: continue
                out.add(o.toApiFlight(o.optString("direction").ifBlank { null }))
            }
            return out
        }

        if (!trimmed.startsWith("{")) return emptyList()
        val obj = JSONObject(trimmed)

        val arrivals = obj.optJSONArray("arrivals")
        if (arrivals != null) {
            for (i in 0 until arrivals.length()) {
                val o = arrivals.optJSONObject(i) ?: continue
                out.add(o.toApiFlight("Arrival"))
            }
        }
        val departures = obj.optJSONArray("departures")
        if (departures != null) {
            for (i in 0 until departures.length()) {
                val o = departures.optJSONObject(i) ?: continue
                out.add(o.toApiFlight("Departure"))
            }
        }
        if (out.isNotEmpty()) return out

        for (key in listOf("flights", "items", "results")) {
            val arr = obj.optJSONArray(key) ?: continue
            for (i in 0 until arr.length()) {
                val o = arr.optJSONObject(i) ?: continue
                out.add(o.toApiFlight(o.optString("direction").ifBlank { null }))
            }
            if (out.isNotEmpty()) return out
        }
        return out
    }

    private fun JSONObject.toApiFlight(dirFallback: String?): ApiFlight {
        val mv = optJSONObject("movement")
            ?: optJSONObject("arrival")
            ?: optJSONObject("departure")
        val dir = (optString("direction").ifBlank {
            when {
                has("arrival") && !has("departure") -> "Arrival"
                has("departure") && !has("arrival") -> "Departure"
                else -> dirFallback ?: ""
            }
        }).takeIf { it.isNotBlank() }
        val quality = ArrayList<String>()
        val qArr = mv?.optJSONArray("quality")
        if (qArr != null) {
            for (j in 0 until qArr.length()) quality.add(qArr.optString(j))
        }
        val status = optString("status").ifBlank { null }
        return ApiFlight(
            direction = dir,
            status = status,
            runwayUtc = extractUtc(mv, "runwayTime") ?: extractUtc(mv, "actualRunway"),
            revisedUtc = extractUtc(mv, "revisedTime") ?: extractUtc(mv, "estimatedTime"),
            actualUtc = extractUtc(mv, "actualTime")
                ?: mv?.optString("actualTimeUtc")?.takeIf { it.isNotBlank() },
            scheduledUtc = extractUtc(mv, "scheduledTime"),
            quality = quality,
            cancelled = mv?.optBoolean("cancelled", false) ?: optBoolean("cancelled", false)
        )
    }","oldString":"    private fun parseFlights(json: String): List<ApiFlight> {
