24:     fun fetchDayCounts(date: LocalDate): Counts {
25:         val zone = TimeFmt.riyadh
26:         val dayStart = date.atStartOfDay(zone)
27:         val nowLdt = LocalDateTime.now(zone)
28:         val dayEnd = date.atTime(23, 59).atZone(zone)
29:         val effectiveEnd = if (date == TimeFmt.today()) nowLdt.atZone(zone) else dayEnd
30: 
31:         if (!effectiveEnd.isAfter(dayStart)) return Counts(0, 0)
32: 
33:         var cursor = dayStart
34:         var arrived = 0
35:         var departed = 0
36:         var raw = 0
37: 
38:         while (cursor.isBefore(effectiveEnd)) {
39:             val windowEndRaw = cursor.plusHours(MAX_WINDOW_HOURS.toLong())
40:             val windowEnd = if (windowEndRaw.isAfter(effectiveEnd)) effectiveEnd else windowEndRaw
41:             val flights = fetchWindow(cursor, windowEnd)
42:             raw += flights.size
43:             for (f in flights) {
44:                 if (f.cancelled) continue
45:                 val st = f.status?.lowercase() ?: ""
46:                 if (st == "canceled" || st == "cancelled" || st == "diverted") continue
47:                 val dir = f.direction?.lowercase() ?: continue
48:                 if (!hasRealMovement(f)) continue
49:                 when (dir) {
50:                     "arrival" -> arrived++
51:                     "departure" -> departed++
52:                 }
53:             }
54:             cursor = windowEnd
55:         }
56: 
57:         return Counts(arrived, departed, raw)
58:     }
