60:     private fun hasRealMovement(f: ApiFlight): Boolean {
61:         val st = f.status?.lowercase() ?: ""
62:         if (st == "arrived" || st == "departed") return true
63:         if (TimeFmt.parseUtc(f.runwayUtc) != null) return true
64:         if (TimeFmt.parseUtc(f.actualUtc) != null) return true
65:         val qLive = f.quality.any { it.equals("live", ignoreCase = true) }
66:         if (qLive) {
67:             val rev = TimeFmt.parseUtc(f.revisedUtc)
68:             if (rev != null) return true
69:         }
70:         val rev = TimeFmt.parseUtc(f.revisedUtc) ?: return false
71:         val sched = TimeFmt.parseUtc(f.scheduledUtc)
72:         if (sched != null && rev != sched) return true
73:         return false
74:     }
