        val mv = optJSONObject("movement") ?: ruhSide
            ?: optJSONObject("arrival") ?: optJSONObject("departure")
        val otherSide = when {
            dir.equals("Arrival", true) -> optJSONObject("departure")
            dir.equals("Departure", true) -> optJSONObject("arrival")
            else -> null
        }

        val quality = ArrayList<String>()
        mv?.optJSONArray("quality")?.let { qArr ->
            for (j in 0 until qArr.length()) quality.add(qArr.optString(j))
        }

        return ApiFlight(
