    private fun extractUtc(mv: JSONObject?, key: String): String? {
        if (mv == null) return null
        val node = mv.optJSONObject(key)
        if (node != null) {
            val utc = node.optString("utc").ifBlank { node.optString("Utc") }
            if (utc.isNotBlank()) return utc
        }
        val flat = mv.optString(key)
        return flat.takeIf { it.isNotBlank() }
    }

    private fun ApiFlight.toDetail(): FlightDetail? {
        val dir = direction?.lowercase() ?: return null
        if (dir != "arrival" && dir != "departure") return null
        val st = status?.lowercase() ?: ""
        if (st == "canceled" || st == "cancelled" || st == "diverted") return null

        val confirmed = hasRealMovement(this)
        val schedInst = TimeFmt.parseUtc(scheduledUtc)
        val actInst = TimeFmt.parseUtc(runwayUtc)
            ?: TimeFmt.parseUtc(actualUtc)
            ?: TimeFmt.parseUtc(revisedUtc)

        val evidence = when {
            TimeFmt.parseUtc(runwayUtc) != null ->
                (if (dir == "arrival") "runway " else "off ") + hm(TimeFmt.parseUtc(runwayUtc))
            TimeFmt.parseUtc(actualUtc) != null -> "actual " + hm(TimeFmt.parseUtc(actualUtc))
            st == "arrived" || st == "departed" -> "status: $st"
            actInst != null && confirmed -> "live " + hm(actInst)
            else -> st.ifBlank { "scheduled only" }
        }

        return FlightDetail(
            dir = dir,
            num = number ?: "?",
            airline = airline ?: "",
            other = otherIata ?: "",
            status = st.ifBlank { "unknown" },
            schedLocal = hm(schedInst),
            actualLocal = if (confirmed) hm(actInst) else null,
            evidence = evidence,
            confirmed = confirmed,
            sortKey = schedInst?.toEpochMilli() ?: 0L
        )
    }

    private fun hm(i: java.time.Instant?): String =
        i?.atZone(TimeFmt.riyadh)?.format(hmFmt) ?: "--:--"
