import java.io.File

class FlightStore(context: Context) {

    private val file = File(context.filesDir, "flight_log.json")
    private val lock = Any()

    fun save(date: String, flights: List<FlightDetail>) {
        synchronized(lock) {
            val root = readRoot()
            val arr = JSONArray()
            for (f in flights) arr.put(f.toJson())
            root.put(date, arr)
            file.writeText(root.toString())
        }
    }

    fun get(date: String): List<FlightDetail> {
        synchronized(lock) {
            val arr = readRoot().optJSONArray(date) ?: return emptyList()
            val out = ArrayList<FlightDetail>(arr.length())
            for (i in 0 until arr.length()) {
                val o = arr.optJSONObject(i) ?: continue
                out.add(FlightDetail.fromJson(o))
            }
            return out
        }
    }

    private fun readRoot(): JSONObject {
        if (!file.exists()) return JSONObject()
        return try {
            JSONObject(file.readText())
        } catch (_: Exception) {
            JSONObject()
        }
    }
}
