    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main)
    private val autoRefresh = Handler(Looper.getMainLooper())
    private var fetching = false

    private var arrExpanded = false
    private var depExpanded = false

    private val tick = object : Runnable {
        override fun run() {
            if (!fetching && store.getKey().isNotBlank()) refresh(silent = true)
            autoRefresh.postDelayed(this, 60 * 60 * 1000L)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityMainBinding.inflate(layoutInflater)
        setContentView(binding.root)

        store = DayStore(this)
        quota = QuotaStore(this)
        flights = FlightStore(this)
        binding.txtQuota.setText(R.string.quota_placeholder)

        ViewCompat.setOnApplyWindowInsetsListener(binding.scrollRoot) { v, insets ->
            val bars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(v.paddingLeft, bars.top + dp(6), v.paddingRight, bars.bottom + dp(8))
            insets
        }

        binding.btnRefresh.setOnClickListener { refresh(silent = false) }
        binding.btnSettings.setOnClickListener { showKeyDialog() }

        binding.headArrived.setOnClickListener { toggleArrived() }
        binding.headDeparted.setOnClickListener { toggleDeparted() }

        RefreshWorker.schedule(this)
        maybeAskNotifPermission()

        showCached()
        if (store.getKey().isBlank()) {
            binding.txtStatus.setText(R.string.no_key)
        } else {
            refresh(silent = false)
        }
    }

    override fun onResume() {
        super.onResume()
        autoRefresh.removeCallbacks(tick)
        autoRefresh.postDelayed(tick, 60 * 60 * 1000L)
    }

    override fun onPause() {
        autoRefresh.removeCallbacks(tick)
        super.onPause()
    }

    override fun onDestroy() {
        autoRefresh.removeCallbacks(tick)
        scope.cancel()
        super.onDestroy()
    }

    private fun maybeAskNotifPermission() {
        if (Build.VERSION.SDK_INT >= 33) {
            if (ContextCompat.checkSelfPermission(this, Manifest.permission.POST_NOTIFICATIONS)
                != PackageManager.PERMISSION_GRANTED
            ) {
                ActivityCompat.requestPermissions(
                    this,
                    arrayOf(Manifest.permission.POST_NOTIFICATIONS),
                    44
                )
            }
        }
        Notifier(this).ensureChannel()
    }

    private fun toggleArrived() {
        arrExpanded = !arrExpanded
        binding.listArrived.visibility = if (arrExpanded) View.VISIBLE else View.GONE
        binding.caretArrived.text = if (arrExpanded) "▾" else "▸"
        if (arrExpanded && binding.listArrived.childCount == 0) renderFlightLists()
    }

    private fun toggleDeparted() {
        depExpanded = !depExpanded
        binding.listDeparted.visibility = if (depExpanded) View.VISIBLE else View.GONE
        binding.caretDeparted.text = if (depExpanded) "▾" else "▸"
        if (depExpanded && binding.listDeparted.childCount == 0) renderFlightLists()
    }

    private fun showCached() {
        val today = TimeFmt.today()
        val todayKey = TimeFmt.pathDate(today)
        val days = store.getDays()
        val todayStat = days[todayKey]
        binding.txtDate.text = TimeFmt.humanDate(today)

        if (todayStat != null) {
            binding.txtArrived.text = todayStat.arrived.toString()
            binding.txtDeparted.text = todayStat.departed.toString()
            val inst = TimeFmt.parseUtc(todayStat.updatedAtIso)
            val flag = if (todayStat.lastFetchOk) "" else " · fetch failed"
            binding.txtMeta.text = "Saved · updated ${TimeFmt.humanTime(inst)}$flag"
        }

        renderFlightLists()
        renderCompare(days, todayKey, todayStat)
        renderHistory(days, todayKey)
        updateQuota()
    }

    private fun renderFlightLists() {
        val todayKey = TimeFmt.pathDate(TimeFmt.today())
        val list = flights.get(todayKey)

        val arrAll = list.filter { it.dir == "arrival" }
        val depAll = list.filter { it.dir == "departure" }
        val arrOk = arrAll.filter { it.confirmed }
        val arrNo = arrAll.filter { !it.confirmed }
        val depOk = depAll.filter { it.confirmed }
        val depNo = depAll.filter { !it.confirmed }

        binding.txtArrivedHeader.text = "ARRIVED · ${arrOk.size}"
        binding.txtArrivedHint.text = when {
            arrOk.isEmpty() && arrNo.isNotEmpty() -> "${arrNo.size} seen, 0 confirmed"
            arrNo.isNotEmpty() -> "+${arrNo.size} unconfirmed"
            else -> ""
        }
        binding.txtDepartedHeader.text = "DEPARTED · ${depOk.size}"
        binding.txtDepartedHint.text = when {
            depOk.isEmpty() && depNo.isNotEmpty() -> "${depNo.size} seen, 0 confirmed"
            depNo.isNotEmpty() -> "+${depNo.size} unconfirmed"
            else -> ""
        }

        fillFlightList(binding.listArrived, arrOk, arrNo, R.color.arrived)
        fillFlightList(binding.listDeparted, depOk, depNo, R.color.departed)
    }

    private fun fillFlightList(
        container: LinearLayout,
        confirmed: List<FlightDetail>,
        unconfirmed: List<FlightDetail>,
        colorRes: Int
    ) {
        container.removeAllViews()
        if (confirmed.isEmpty() && unconfirmed.isEmpty()) {
            container.addView(TextView(this).apply {
                text = "No flights recorded"
                setTextColor(getColor(R.color.text_secondary))
                textSize = 13f
                setPadding(dp(4), dp(8), dp(4), dp(8))
            })
            return
        }
        for (f in confirmed) container.addView(flightRow(f, colorRes, false))
        if (unconfirmed.isNotEmpty()) {
            container.addView(TextView(this).apply {
                text = "— not confirmed —"
                setTextColor(getColor(R.color.text_secondary))
                textSize = 11f
                gravity = Gravity.CENTER
                setPadding(dp(4), dp(12), dp(4), dp(4))
            })
            for (f in unconfirmed) container.addView(flightRow(f, colorRes, true))
        }
    }

