        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            addView(input)
            addView(testBtn)
        }

        val dialog = AlertDialog.Builder(this)
            .setTitle(R.string.settings)
            .setMessage("Paste your AeroDataBox key from RapidAPI.")
            .setView(root)
            .setPositiveButton(R.string.save) { _, _ ->
                store.setKey(input.text.toString())
                refresh(silent = false)
            }
            .setNegativeButton(R.string.cancel, null)
            .create()

        testBtn.setOnClickListener {
            val k = input.text.toString().trim()
            if (k.isBlank()) {
                Toast.makeText(this, "Enter a key first", Toast.LENGTH_SHORT).show()
                return@setOnClickListener
            }
            testBtn.text = "Testing…"
            testBtn.isEnabled = false
            scope.launch(Dispatchers.IO) {
                val msg = try {
                    val c = AeroDataBoxClient(k) { hdrs ->
                        quota.recordHeaders(hdrs)
                        quota.recordCall()
                        runOnUiThread { updateQuota() }
                    }
                    c.testKey()
                } catch (e: ApiException) {
                    "FAILED — HTTP ${e.code}: ${e.message?.take(60)}"
                } catch (e: Exception) {
                    "FAILED — network error"
                }
                launch(Dispatchers.Main) {
                    testBtn.isEnabled = true
                    testBtn.text = msg
                    if (msg.startsWith("Key OK")) {
                        testBtn.setTextColor(getColor(R.color.arrived))
                    } else {
                        testBtn.setTextColor(getColor(R.color.error))
                    }
                }
            }
        }

        dialog.show()
    }

    private fun dp(v: Int): Int =
        (v * resources.displayMetrics.density).toInt()
