class ApiException(val code: Int, body: String) : Exception("HTTP $code: ${body.take(180)}")

private fun httpGet(
    urlStr: String,
    headers: Map<String, String>,
    onCall: ((Map<String, String>) -> Unit)?
): String {
    val conn = URL(urlStr).openConnection() as HttpURLConnection
    try {
        conn.requestMethod = "GET"
        conn.connectTimeout = 25000
        conn.readTimeout = 25000
        for ((k, v) in headers) conn.setRequestProperty(k, v)
        conn.setRequestProperty("Accept", "application/json")
        val code = conn.responseCode
        try {
            val hdrs = HashMap<String, String>()
            for ((k, v) in conn.headerFields) {
                if (k != null && v != null && v.isNotEmpty()) hdrs[k] = v[0]
            }
            onCall?.invoke(hdrs)
        } catch (_: Exception) {
        }
        if (code !in 200..299) {
            val err = conn.errorStream?.bufferedReader()?.use(BufferedReader::readText) ?: ""
            throw ApiException(code, err)
        }
        return conn.inputStream.bufferedReader().use(BufferedReader::readText)
    } finally {
        conn.disconnect()
    }
}

class AeroDataBoxSource(
    private val key: String,
    private val onCall: ((Map<String, String>) -> Unit)? = null
) : FlightSource {

    override val id = Sources.AERODATABOX

    companion object {
        private const val HOST = "aerodatabox.p.rapidapi.com"
        private const val BASE = "https://aerodatabox.p.rapidapi.com"
        private const val IATA = "RUH"
        private const val MAX_WINDOW_HOURS = 11
    }

    private fun headers() = mapOf(
        "X-RapidAPI-Key" to key,
        "X-RapidAPI-Host" to HOST
    )

    private fun enc(s: String) = URLEncoder.encode(s, "UTF-8")

    override fun test(): String {
        val now = LocalDateTime.now(TimeFmt.riyadh)
        val from = TimeFmt.localPath(now.minusHours(1).atZone(TimeFmt.riyadh).toInstant())
        val to = TimeFmt.localPath(now.atZone(TimeFmt.riyadh).toInstant())
        val url =
            "$BASE/flights/airports/iata/$IATA/${enc(from)}/${enc(to)}?withLeg=false&direction=Both&withCancelled=false"
        val flights = parseFlights(httpGet(url, headers(), onCall))
        return "Key OK — ${flights.size} flight(s) in last hour"
    }

    override fun fetchDay(date: LocalDate): DayFetch {
        val zone = TimeFmt.riyadh
        val dayStart = date.atStartOfDay(zone)
        val nowLdt = LocalDateTime.now(zone)
        val effectiveEnd =
            if (date == TimeFmt.today()) nowLdt.atZone(zone) else date.atTime(23, 59).atZone(zone)
        if (!effectiveEnd.isAfter(dayStart)) return DayFetch.of(emptyList(), 0)

        var cursor = dayStart
        var raw = 0
        val all = LinkedHashMap<String, ApiFlight>()
        while (cursor.isBefore(effectiveEnd)) {
            val endRaw = cursor.plusHours(MAX_WINDOW_HOURS.toLong())
            val end = if (endRaw.isAfter(effectiveEnd)) effectiveEnd else endRaw
            val flights = fetchWindow(cursor, end)
            raw += flights.size
            for (f in flights) {
                all[(f.direction ?: "?") + "/" + (f.number ?: f.hashCode().toString())] = f
            }
            cursor = end
        }
        val details = all.values.mapNotNull { it.toDetail(date) }
            .sortedWith(compareBy({ it.dir != "departure" }, { it.sortKey }))
        return DayFetch.of(details, raw)
    }

    private fun fetchWindow(s: ZonedDateTime, e: ZonedDateTime): List<ApiFlight> {
        val from = TimeFmt.localPath(s.toInstant())
        val to = TimeFmt.localPath(e.toInstant())
        val qs =
            "withLeg=true&direction=Both&withCancelled=false&withCodeshared=false&withCargo=false&withPrivate=false"
        return parseFlights(
            httpGet("$BASE/flights/airports/iata/$IATA/${enc(from)}/${enc(to)}?$qs", headers(), onCall)
        )
    }

    private fun parseFlights(json: String): List<ApiFlight> {
        val trimmed = json.trim()
        if (trimmed.isEmpty() || trimmed == "null") return emptyList()
        val out = ArrayList<ApiFlight>()

        if (trimmed.startsWith("[")) {
            val arr = JSONArray(trimmed)
            for (i in 0 until arr.length()) {
                val o = arr.optJSONObject(i) ?: continue
                out.add(o.toApiFlight(o.optString("direction")))
            }
            return out
        }
        if (!trimmed.startsWith("{")) return emptyList()
        val obj = JSONObject(trimmed)
        obj.optJSONArray("arrivals")?.let { arr ->
            for (i in 0 until arr.length()) arr.optJSONObject(i)?.let { out.add(it.toApiFlight("Arrival")) }
        }
        obj.optJSONArray("departures")?.let { arr ->
            for (i in 0 until arr.length()) arr.optJSONObject(i)?.let { out.add(it.toApiFlight("Departure")) }
        }
        if (out.isNotEmpty()) return out
        for (k in listOf("flights", "items", "results")) {
            val arr = obj.optJSONArray(k) ?: continue
            for (i in 0 until arr.length()) {
                arr.optJSONObject(i)?.let { out.add(it.toApiFlight(it.optString("direction"))) }
            }
            if (out.isNotEmpty()) return out
        }
        return out
    }

    private fun JSONObject.toApiFlight(dirHint: String): ApiFlight {
        val dir = dirHint.ifBlank {
            when {
                has("arrival") && !has("departure") -> "Arrival"
                has("departure") && !has("arrival") -> "Departure"
                else -> ""
            }
        }
        val arrivalSide = optJSONObject("arrival")
        val departureSide = optJSONObject("departure")
        val ruhSide = when {
            dir.equals("Arrival", true) -> arrivalSide
            dir.equals("Departure", true) -> departureSide
            else -> null
        }
        val otherSide = when {
            dir.equals("Arrival", true) -> departureSide
            dir.equals("Departure", true) -> arrivalSide
            else -> null
        }
        val mv = optJSONObject("movement") ?: ruhSide ?: arrivalSide ?: departureSide

        return ApiFlight(
            direction = dir.takeIf { it.isNotBlank() },
            status = optString("status").ifBlank { null },
            number = optString("number").ifBlank { null },
            airline = optJSONObject("airline")?.optString("name")?.ifBlank { null },
            otherIata = otherSide?.optJSONObject("airport")?.optString("iataCode")?.ifBlank { null },
            runwayUtc = xUtc(mv, "runwayTime") ?: xUtc(mv, "actualRunway"),
            revisedUtc = xUtc(mv, "revisedTime") ?: xUtc(mv, "estimatedTime"),
            actualUtc = xUtc(mv, "actualTime") ?: mv?.optString("actualTimeUtc")?.b(),
            scheduledUtc = xUtc(mv, "scheduledTime"),
            quality = xQ(mv),
            cancelled = mv?.optBoolean("cancelled", false) ?: optBoolean("cancelled", false),
            oRunwayUtc = xUtc(otherSide, "runwayTime") ?: xUtc(otherSide, "actualRunway"),
            oActualUtc = xUtc(otherSide, "actualTime"),
            oRevisedUtc = xUtc(otherSide, "revisedTime") ?: xUtc(otherSide, "estimatedTime"),
            oScheduledUtc = xUtc(otherSide, "scheduledTime"),
            oQuality = xQ(otherSide)
        )
    }

    private fun String?.b(): String? = this?.takeIf { it.isNotBlank() }

    private fun xQ(mv: JSONObject?): List<String> {
        val out = ArrayList<String>()
        mv?.optJSONArray("quality")?.let { a ->
            for (i in 0 until a.length()) out.add(a.optString(i))
        }
        return out
    }

    private fun xUtc(mv: JSONObject?, k: String): String? {
        if (mv == null) return null
        val node = mv.optJSONObject(k)
        if (node != null) {
            val u = node.optString("utc").ifBlank { node.optString("Utc") }
            if (u.isNotBlank()) return u
        }
        return mv.optString(k).takeIf { it.isNotBlank() }
    }

    private fun realAt(runway: String?, actual: String?, revised: String?, sched: String?, q: List<String>): String? {
        TimeFmt.parseUtc(runway)?.let { return TimeFmt.hhmm(runway) }
        TimeFmt.parseUtc(actual)?.let { return TimeFmt.hhmm(actual) }
        val live = q.any { it.equals("live", true) }
        val rev = TimeFmt.parseUtc(revised) ?: return null
        if (live) return TimeFmt.hhmm(revised)
        val sc = TimeFmt.parseUtc(sched)
        if (sc != null && rev != sc) return TimeFmt.hhmm(revised)
        return null
    }

    private fun ApiFlight.toDetail(date: LocalDate): FlightDetail? {
        val dir = direction?.lowercase() ?: return null
        if (dir != "arrival" && dir != "departure") return null
        val st = (status ?: "").lowercase()
        if (st == "canceled" || st == "cancelled" || st == "diverted") return null

        val depRealT: String?   // real dep: origin for arrivals, RUH for departures
        val arrRealT: String?   // real arr: RUH for arrivals, destination for departures
        val depSchedT: String?
        val arrSchedT: String?

        if (dir == "departure") {
            depRealT = realAt(runwayUtc, actualUtc, revisedUtc, scheduledUtc, quality)
            arrRealT = realAt(oRunwayUtc, oActualUtc, oRevisedUtc, oScheduledUtc, oQuality)
            depSchedT = TimeFmt.hhmm(scheduledUtc)
            arrSchedT = TimeFmt.hhmm(oScheduledUtc)
        } else {
            depRealT = realAt(oRunwayUtc, oActualUtc, oRevisedUtc, oScheduledUtc, oQuality)
            arrRealT = realAt(runwayUtc, actualUtc, revisedUtc, scheduledUtc, quality)
            depSchedT = TimeFmt.hhmm(oScheduledUtc)
            arrSchedT = TimeFmt.hhmm(scheduledUtc)
        }

        val confirmed = when (dir) {
            "departure" -> depRealT != null || st == "departed"
            else -> depRealT != null && (arrRealT != null || st == "arrived")
        }

        val evidence = when {
            confirmed && dir == "departure" -> "real dep $depRealT"
            confirmed -> "dep $depRealT · arr $arrRealT"
            else -> "status: ${st.ifBlank { "scheduled only" }}"
        }

        val sortSide = if (dir == "departure") depSchedT else arrSchedT
        return FlightDetail(
            dir = dir,
            num = number ?: "?",
            airline = airline ?: "",
            other = otherIata ?: "",
            status = st.ifBlank { "unknown" },
            depReal = depRealT,
            arrReal = arrRealT,
            depSched = depSchedT,
            arrSched = arrSchedT,
            evidence = evidence,
            confirmed = confirmed,
            src = id,
            sortKey = TimeFmt.sortKey(date, sortSide)
        )
    }
}

class AviationstackSource(
    private val key: String,
    private val onCall: ((Map<String, String>) -> Unit)? = null
) : FlightSource {

    override val id = Sources.AVIATIONSTACK

    companion object {
        private const val BASE = "https://api.aviationstack.com/v1/flights"
        private const val PAGE = 100
    }

    override fun test(): String {
        val url = "$BASE?access_key=${enc(key)}&arr_iata=RUH&limit=1"
        val body = httpGet(url, emptyMap(), onCall)
        checkError(body)
        val n = parseData(body).size
        return "Key OK — ${n} flight(s) sample"
    }

    override fun fetchDay(date: LocalDate): DayFetch {
        val dateStr = TimeFmt.pathDate(date)
        val all = ArrayList<FlightDetail>()
        var raw = 0

        for (dirParam in listOf("arr_iata", "dep_iata")) {
            var offset = 0
            var pages = 0
            while (pages < 6) {
                val url = "$BASE?access_key=${enc(key)}&$dirParam=RUH&flight_date=$dateStr" +
                        "&limit=$PAGE&offset=$offset"
                val body = httpGet(url, emptyMap(), onCall)
                checkError(body)
                val items = parseData(body)
                raw += items.size
                for (o in items) {
                    val d = parseFlight(o, dirParam, date) ?: continue
                    all.add(d)
                }
                val total = JSONObject(body).optJSONObject("pagination")?.optInt("total") ?: 0
                offset += PAGE
                pages++
                if (offset >= total || items.size < PAGE) break
            }
        }

        val dedup = LinkedHashMap<String, FlightDetail>()
        for (f in all) dedup[f.dir + "/" + f.num] = f
        val list = dedup.values.sortedWith(
            compareBy({ it.dir != "departure" }, { it.sortKey }, { it.num })
        )
        return DayFetch.of(list, raw)
    }

    private fun enc(s: String) = URLEncoder.encode(s, "UTF-8")

    private fun checkError(body: String) {
        val t = body.trim()
        if (t.startsWith("{")) {
            val o = JSONObject(t)
            if (o.has("error")) {
                val e = o.optJSONObject("error")
                throw ApiException(
                    e?.optInt("code") ?: 400,
                    e?.optString("info") ?: t
                )
            }
        }
    }

    private fun parseData(body: String): List<JSONObject> {
        val t = body.trim()
        if (!t.startsWith("{")) return emptyList()
        val arr = JSONObject(t).optJSONArray("data") ?: return emptyList()
        val out = ArrayList<JSONObject>(arr.length())
        for (i in 0 until arr.length()) {
            val o = arr.optJSONObject(i) ?: continue
            if (!o.isNull("codeshared")) continue
            out.add(o)
        }
        return out
    }

    private fun parseFlight(o: JSONObject, dirParam: String, date: LocalDate): FlightDetail? {
        val dep = o.optJSONObject("departure") ?: return null
        val arr = o.optJSONObject("arrival") ?: return null
        val flight = o.optJSONObject("flight")
        val airline = o.optJSONObject("airline")
        val st = o.optString("flight_status").lowercase()
        if (st == "cancelled" || st == "diverted") return null

        val num = flight?.optString("iataNumber")?.ifBlank { null }
            ?: run {
                val n = flight?.optString("number") ?: return null
                (airline?.optString("iataCode") ?: "") + n
            }

        val dir = if (dirParam == "arr_iata") "arrival" else "departure"
        val otherObj = if (dir == "arrival") dep else arr
        val ruhObj = if (dir == "arrival") arr else dep

        val depReal = TimeFmt.hhmm(dep.optString("actualRunway").ifBlank { dep.optString("actualTime") })
        val arrReal = TimeFmt.hhmm(arr.optString("actualRunway").ifBlank { arr.optString("actualTime") })
        val depSched = TimeFmt.hhmm(dep.optString("scheduledTime"))
        val arrSched = TimeFmt.hhmm(arr.optString("scheduledTime"))

        val confirmed = when (dir) {
            "departure" -> depReal != null || st == "active" || st == "landed"
            else -> depReal != null && (arrReal != null || st == "landed")
        }

        val evidence = when {
            confirmed && dir == "departure" -> "real dep $depReal"
            confirmed && depReal != null && arrReal != null -> "dep $depReal · arr $arrReal"
            confirmed && st == "landed" -> "status: landed"
            else -> "status: ${st.ifBlank { "scheduled only" }}"
        }

        val sortSide = if (dir == "departure") depSched else arrSched
        return FlightDetail(
            dir = dir,
            num = num,
            airline = airline?.optString("name") ?: "",
            other = otherObj.optString("iataCode") ?: "",
            status = st.ifBlank { "unknown" },
            depReal = depReal,
            arrReal = arrReal,
            depSched = depSched,
            arrSched = arrSched,
            evidence = evidence,
            confirmed = confirmed,
            src = id,
            sortKey = TimeFmt.sortKey(date, sortSide)
        )
    }
}
