        val todayKey = TimeFmt.pathDate(today)
        val days = store.getDays()
        val todayStat = days[todayKey]
        binding.txtDate.text = TimeFmt.humanDate(today)

        if (todayStat != null) {
            binding.txtArrived.text = todayStat.arrived.toString()
            binding.txtDeparted.text = todayStat.departed.toString()
            val inst = TimeFmt.parseUtc(todayStat.updatedAtIso)
            val flag = if (todayStat.lastFetchOk) "" else " · fetch failed"
            binding.txtMeta.text = "Saved · updated ${TimeFmt.humanTime(inst)}$flag"
        }

        binding.txtApiStatus.setTextColor(
            getColor(if (store.lastApiOk()) R.color.arrived else R.color.error)
        )
        binding.txtApiStatus.text = store.lastApiMsg().ifBlank { "API: not tested yet" }

        renderFlightLists()
        renderCompare(days, todayKey, todayStat)
        renderHistory(days, todayKey)
        updateQuota()
    }

    private fun renderFlightLists() {
        val todayKey = TimeFmt.pathDate(TimeFmt.today())
        val list = flights.get(todayKey)

        val arrAll = list.filter { it.dir == "arrival" }
        val depAll = list.filter { it.dir == "departure" }
        val arrOk = arrAll.filter { it.confirmed }
        val arrNo = arrAll.filter { !it.confirmed }
        val depOk = depAll.filter { it.confirmed }
        val depNo = depAll.filter { !it.confirmed }

        binding.txtArrivedHeader.text = "ARRIVED · ${arrOk.size}"
        binding.txtArrivedHint.text = when {
            arrOk.isEmpty() && arrNo.isNotEmpty() -> "${arrNo.size} seen, 0 confirmed"
            arrNo.isNotEmpty() -> "+${arrNo.size} unconfirmed"
            else -> ""
        }
        binding.txtDepartedHeader.text = "DEPARTED · ${depOk.size}"
        binding.txtDepartedHint.text = when {
            depOk.isEmpty() && depNo.isNotEmpty() -> "${depNo.size} seen, 0 confirmed"
            depNo.isNotEmpty() -> "+${depNo.size} unconfirmed"
            else -> ""
        }

        fillFlightList(binding.listArrived, arrOk, arrNo, R.color.arrived)
        fillFlightList(binding.listDeparted, depOk, depNo, R.color.departed)
