    private fun backfillDates(today: java.time.LocalDate): List<java.time.LocalDate> {
        val depth = today.dayOfWeek.value % 7
        return (1..depth).map { today.minusDays(it.toLong()) }
    }

    private fun refresh(silent: Boolean) {
        val srcId = store.activeSource()
        val src = buildSource(srcId)
        if (src == null) {
            if (!silent) Toast.makeText(this, R.string.no_key, Toast.LENGTH_SHORT).show()
            setApiStatus(false, "No key for ${Sources.label(srcId)}")
            return
        }
        if (fetching) return
        fetching = true
        binding.progress.visibility = View.VISIBLE
        if (!silent) binding.txtStatus.setText(R.string.loading)

        val today = TimeFmt.today()
        val todayKey = TimeFmt.pathDate(today)
        val notifier = Notifier(this)

        scope.launch(Dispatchers.IO) {
            var err: Exception? = null
            var dayFetch: DayFetch? = null
            val backfilled = HashMap<String, DayFetch>()
            val oldToday = flights.get(todayKey)

            try {
                dayFetch = src.fetchDay(today)
                val existing = store.getDays()
                for (d in backfillDates(today)) {
                    val k = TimeFmt.pathDate(d)
                    val stat = existing[k]
                    if (stat == null || !stat.lastFetchOk || stat.sv < SCHEMA_V) {
                        backfilled[k] = src.fetchDay(d)
                    }
                }
            } catch (e: Exception) {
                err = e
            }

            launch(Dispatchers.Main) {
                fetching = false
                binding.progress.visibility = View.GONE
                val srcLabel = Sources.label(srcId)

                if (err != null) {
                    val msg = when (err) {
                        is ApiException -> "API error ${err.code}"
                        else -> "Network error"
                    }
                    binding.txtStatus.setTextColor(getColor(R.color.error))
                    binding.txtStatus.text = msg
                    setApiStatus(false, "$srcLabel: FAILED — $msg")
                    val prev = store.getDays()[todayKey]
                    if (prev != null && prev.lastFetchOk) notifier.apiError(msg)
                    if (prev != null) {
                        store.saveDay(
                            prev.copy(
                                updatedAtIso = Instant.now().toString(),
                                lastFetchOk = false,
                                errorMsg = err.message,
                                sv = SCHEMA_V
                            )
                        )
                    }
                    showCached()
                    return@launch
                }

                val df = dayFetch ?: DayFetch.of(emptyList(), 0)
                val mergedToday = FlightMerge.merge(df.flights, oldToday)
                val counts = FlightMerge.counts(mergedToday, df.counts.raw)

                val prev = store.getDays()[todayKey]
                if (prev != null && counts.arrived > prev.arrived) {
                    notifier.arrivalsIncreased(counts.arrived, prev.arrived)
                }
                store.saveDay(
                    DayStat(
                        date = todayKey,
                        arrived = counts.arrived,
                        departed = counts.departed,
                        updatedAtIso = Instant.now().toString(),
                        lastFetchOk = true,
                        errorMsg = null,
                        sv = SCHEMA_V
                    )
                )
                flights.save(todayKey, mergedToday)

                for ((k, bf) in backfilled) {
                    val mergedDay = FlightMerge.merge(bf.flights, flights.get(k))
                    val c = FlightMerge.counts(mergedDay, bf.counts.raw)
                    store.saveDay(
                        DayStat(
                            date = k,
                            arrived = c.arrived,
                            departed = c.departed,
                            updatedAtIso = Instant.now().toString(),
                            lastFetchOk = true,
                            errorMsg = null,
                            sv = SCHEMA_V
                        )
                    )
                    flights.save(k, mergedDay)
                }

                setApiStatus(true, "$srcLabel: OK")
                binding.txtStatus.setTextColor(getColor(R.color.text_secondary))
                binding.txtStatus.text =
                    "Only flights with real times · ${counts.raw} seen in API"
                showCached()
            }
        }
    }

