import android.content.Context
import androidx.work.CoroutineWorker
import androidx.work.ExistingPeriodicWorkPolicy
import androidx.work.PeriodicWorkRequestBuilder
import androidx.work.WorkManager
import androidx.work.WorkerParameters
import java.time.Instant
import java.util.concurrent.TimeUnit

class RefreshWorker(
    context: Context,
    params: WorkerParameters
) : CoroutineWorker(context, params) {

    companion object {
        const val NAME = "ruh-refresh"

        fun schedule(context: Context) {
            val req = PeriodicWorkRequestBuilder<RefreshWorker>(30, TimeUnit.MINUTES).build()
            WorkManager.getInstance(context).enqueueUniquePeriodicWork(
                NAME,
                ExistingPeriodicWorkPolicy.KEEP,
                req
            )
        }

        fun backfillDates(today: java.time.LocalDate): List<java.time.LocalDate> {
            val depth = today.dayOfWeek.value % 7
            return (1..depth).map { today.minusDays(it.toLong()) }
        }

        private fun buildSource(
            store: DayStore,
            quota: QuotaStore,
            srcId: String
        ): FlightSource? {
            val key = store.keyFor(srcId)
            if (key.isBlank()) return null
            val onCall: (Map<String, String>) -> Unit = { h ->
                quota.recordHeaders(srcId, h)
                quota.recordCall(srcId)
            }
            return when (srcId) {
                Sources.AERODATABOX -> AeroDataBoxSource(key, onCall)
                Sources.AVIATIONSTACK -> AviationstackSource(key, onCall)
                else -> null
            }
        }
    }

    override suspend fun doWork(): Result {
        val store = DayStore(applicationContext)
        val quota = QuotaStore(applicationContext)
        val flightStore = FlightStore(applicationContext)
        val srcId = store.activeSource()
        val src = buildSource(store, quota, srcId) ?: return Result.success()

        val notifier = Notifier(applicationContext)
        val today = TimeFmt.today()
        val todayKey = TimeFmt.pathDate(today)
        val days = store.getDays()
        val prevToday = days[todayKey]

        return try {
            val df = src.fetchDay(today)
            val merged = FlightMerge.merge(df.flights, flightStore.get(todayKey))
            val counts = FlightMerge.counts(merged, df.counts.raw)

            if (prevToday != null && counts.arrived > prevToday.arrived) {
                notifier.arrivalsIncreased(counts.arrived, prevToday.arrived)
            }
            store.saveDay(
                DayStat(
                    date = todayKey,
                    arrived = counts.arrived,
                    departed = counts.departed,
                    updatedAtIso = Instant.now().toString(),
                    lastFetchOk = true,
                    errorMsg = null,
                    sv = SCHEMA_V
                )
            )
            flightStore.save(todayKey, merged)

            val existing = store.getDays()
            for (d in backfillDates(today)) {
                val k = TimeFmt.pathDate(d)
                val stat = existing[k]
                if (stat == null || !stat.lastFetchOk || stat.sv < SCHEMA_V) {
                    val bf = src.fetchDay(d)
                    val bfMerged = FlightMerge.merge(bf.flights, flightStore.get(k))
                    val bfCounts = FlightMerge.counts(bfMerged, bf.counts.raw)
                    store.saveDay(
                        DayStat(
                            date = k,
                            arrived = bfCounts.arrived,
                            departed = bfCounts.departed,
                            updatedAtIso = Instant.now().toString(),
                            lastFetchOk = true,
                            errorMsg = null,
                            sv = SCHEMA_V
                        )
                    )
                    flightStore.save(k, bfMerged)
                }
            }

            store.setLastApi(true, "${Sources.label(srcId)}: OK")
            Result.success()
        } catch (e: Exception) {
            val msg = when (e) {
                is ApiException -> "API error ${e.code}"
                else -> "Network error"
            }
            val stamped = prevToday?.copy(
                updatedAtIso = Instant.now().toString(),
                lastFetchOk = false,
                errorMsg = e.message,
                sv = SCHEMA_V
            )
            if (stamped != null) store.saveDay(stamped)

            store.setLastApi(false, "${Sources.label(srcId)}: FAILED — $msg")
            if (prevToday != null && prevToday.lastFetchOk) {
                notifier.apiError(msg)
            }
            if (e is ApiException && (e.code == 401 || e.code == 403)) {
                return Result.failure()
            }
            Result.retry()
        }
    }
}
