    private fun String?.b(): String? = this?.takeIf { it.isNotBlank() }

    private fun xQ(mv: JSONObject?): List<String> {
        val out = ArrayList<String>()
        mv?.optJSONArray("quality")?.let { a ->
            for (i in 0 until a.length()) out.add(a.optString(i))
        }
        return out
    }

    private fun xUtc(mv: JSONObject?, k: String): String? {
        if (mv == null) return null
        val node = mv.optJSONObject(k)
        if (node != null) {
            val u = node.optString("utc").ifBlank { node.optString("Utc") }
            if (u.isNotBlank()) return u
        }
        return mv.optString(k).takeIf { it.isNotBlank() }
    }

    private fun realAt(runway: String?, actual: String?, revised: String?, sched: String?, q: List<String>): String? {
        TimeFmt.parseUtc(runway)?.let { return TimeFmt.hhmm(runway) }
        TimeFmt.parseUtc(actual)?.let { return TimeFmt.hhmm(actual) }
        val live = q.any { it.equals("live", true) }
        val rev = TimeFmt.parseUtc(revised) ?: return null
        if (live) return TimeFmt.hhmm(revised)
        val sc = TimeFmt.parseUtc(sched)
        if (sc != null && rev != sc) return TimeFmt.hhmm(revised)
        return null
    }

    private fun ApiFlight.toDetail(date: LocalDate): FlightDetail? {
        val dir = direction?.lowercase() ?: return null
        if (dir != "arrival" && dir != "departure") return null
        val st = (status ?: "").lowercase()
        if (st == "canceled" || st == "cancelled" || st == "diverted") return null

        val depRealT: String?   // real dep: origin for arrivals, RUH for departures
        val arrRealT: String?   // real arr: RUH for arrivals, destination for departures
        val depSchedT: String?
        val arrSchedT: String?

        if (dir == "departure") {
            depRealT = realAt(runwayUtc, actualUtc, revisedUtc, scheduledUtc, quality)
            arrRealT = realAt(oRunwayUtc, oActualUtc, oRevisedUtc, oScheduledUtc, oQuality)
            depSchedT = TimeFmt.hhmm(scheduledUtc)
            arrSchedT = TimeFmt.hhmm(oScheduledUtc)
        } else {
            depRealT = realAt(oRunwayUtc, oActualUtc, oRevisedUtc, oScheduledUtc, oQuality)
            arrRealT = realAt(runwayUtc, actualUtc, revisedUtc, scheduledUtc, quality)
            depSchedT = TimeFmt.hhmm(oScheduledUtc)
            arrSchedT = TimeFmt.hhmm(scheduledUtc)
        }

        val confirmed = when (dir) {
            "departure" -> depRealT != null || st == "departed"
            else -> depRealT != null && (arrRealT != null || st == "arrived")
        }

        val evidence = when {
            confirmed && dir == "departure" -> "real dep $depRealT"
            confirmed -> "dep $depRealT · arr $arrRealT"
            else -> "status: ${st.ifBlank { "scheduled only" }}"
        }

        val sortSide = if (dir == "departure") depSchedT else arrSchedT
        return FlightDetail(
            dir = dir,
            num = number ?: "?",
            airline = airline ?: "",
            other = otherIata ?: "",
            status = st.ifBlank { "unknown" },
            depReal = depRealT,
            arrReal = arrRealT,
            depSched = depSchedT,
            arrSched = arrSchedT,
            evidence = evidence,
            confirmed = confirmed,
            src = id,
            sortKey = TimeFmt.sortKey(date, sortSide)
        )
    }
}

