    private fun showKeyDialog() {
        val activeIdx = Sources.all.keys.indexOf(store.activeSource()).coerceAtLeast(0)

        val spin = Spinner(this).apply {
            adapter = ArrayAdapter(
                this@MainActivity,
                android.R.layout.simple_spinner_dropdown_item,
                Sources.all.values.toList()
            )
            setSelection(activeIdx)
        }
        val boxKey = EditText(this).apply {
            hint = "AeroDataBox key (RapidAPI)"
            inputType = InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_VARIATION_PASSWORD
            setText(store.keyFor(Sources.AERODATABOX))
            setSelection(text.length)
        }
        val stackKey = EditText(this).apply {
            hint = "Aviationstack key (access_key)"
            inputType = InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_VARIATION_PASSWORD
            setText(store.keyFor(Sources.AVIATIONSTACK))
            setSelection(text.length)
        }
        val testBtn = TextView(this).apply {
            text = getString(R.string.test_key)
            setTextColor(getColor(R.color.accent))
            textSize = 15f
            setTypeface(null, android.graphics.Typeface.BOLD)
            gravity = Gravity.CENTER
            setPadding(dp(20), dp(12), dp(20), dp(4))
        }

        fun labelFor(i: Int): String = Sources.all.keys.toList().getOrElse(i) { Sources.AERODATABOX }
        val hint = TextView(this).apply {
            text = "Pick the active source. Each keeps its own key."
            setTextColor(getColor(R.color.text_secondary))
            textSize = 12f
            setPadding(dp(20), dp(8), dp(20), 0)
        }

        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), 0, dp(20), 0)
            addView(hint)
            addView(spin)
            addView(boxKey)
            addView(stackKey)
            addView(testBtn)
        }

        AlertDialog.Builder(this)
            .setTitle("Sources & API keys")
            .setView(root)
            .setPositiveButton(R.string.save) { _, _ ->
                store.setKeyFor(Sources.AERODATABOX, boxKey.text.toString())
                store.setKeyFor(Sources.AVIATIONSTACK, stackKey.text.toString())
                store.setActiveSource(labelFor(spin.selectedItemPosition))
                refresh(silent = false)
            }
            .setNegativeButton(R.string.cancel, null)
            .show()

        testBtn.setOnClickListener {
            val srcId = labelFor(spin.selectedItemPosition)
            val key = when (srcId) {
                Sources.AVIATIONSTACK -> stackKey.text.toString().trim()
                else -> boxKey.text.toString().trim()
            }
            if (key.isBlank()) {
                Toast.makeText(this, "Enter a key first", Toast.LENGTH_SHORT).show()
                return@setOnClickListener
            }
            testBtn.text = "Testing…"
            testBtn.isEnabled = false
            scope.launch(Dispatchers.IO) {
                val msg = try {
                    val onCall: (Map<String, String>) -> Unit = { h ->
                        quota.recordHeaders(srcId, h)
                        quota.recordCall(srcId)
                        runOnUiThread { updateQuota() }
                    }
                    val s = when (srcId) {
                        Sources.AVIATIONSTACK -> AviationstackSource(key, onCall)
                        else -> AeroDataBoxSource(key, onCall)
                    }
                    s.test()
                } catch (e: ApiException) {
                    "FAILED — HTTP ${e.code}: ${e.message?.take(60)}"
                } catch (e: Exception) {
                    "FAILED — network error"
                }
                launch(Dispatchers.Main) {
                    testBtn.isEnabled = true
                    testBtn.text = msg
                    testBtn.setTextColor(
                        getColor(if (msg.startsWith("Key OK")) R.color.arrived else R.color.error)
                    )
                    setApiStatus(msg.startsWith("Key OK"), "${Sources.label(srcId)}: ${msg.take(70)}")
                }
            }
        }
    }

    private fun dp(v: Int): Int =
        (v * resources.displayMetrics.density).toInt()
