    private fun JSONObject.toApiFlight(dirHint: String): ApiFlight {
        val dir = dirHint.ifBlank {
            when {
                has("arrival") && !has("departure") -> "Arrival"
                has("departure") && !has("arrival") -> "Departure"
                else -> ""
            }
        }
        val arrivalSide = optJSONObject("arrival")
        val departureSide = optJSONObject("departure")
        val ruhSide = when {
            dir.equals("Arrival", true) -> arrivalSide
            dir.equals("Departure", true) -> departureSide
            else -> null
        }
        val otherSide = when {
            dir.equals("Arrival", true) -> departureSide
            dir.equals("Departure", true) -> arrivalSide
            else -> null
        }
        val mv = optJSONObject("movement") ?: ruhSide ?: arrivalSide ?: departureSide

        return ApiFlight(
            direction = dir.takeIf { it.isNotBlank() },
            status = optString("status").ifBlank { null },
            number = optString("number").ifBlank { null },
            airline = optJSONObject("airline")?.optString("name")?.ifBlank { null },
            otherIata = otherSide?.optJSONObject("airport")?.optString("iataCode")?.ifBlank { null },
            runwayUtc = xUtc(mv, "runwayTime") ?: xUtc(mv, "actualRunway"),
            revisedUtc = xUtc(mv, "revisedTime") ?: xUtc(mv, "estimatedTime"),
            actualUtc = xUtc(mv, "actualTime") ?: mv?.optString("actualTimeUtc")?.b(),
            scheduledUtc = xUtc(mv, "scheduledTime"),
            quality = xQ(mv),
            cancelled = mv?.optBoolean("cancelled", false) ?: optBoolean("cancelled", false),
            oRunwayUtc = xUtc(otherSide, "runwayTime") ?: xUtc(otherSide, "actualRunway"),
            oActualUtc = xUtc(otherSide, "actualTime"),
            oRevisedUtc = xUtc(otherSide, "revisedTime") ?: xUtc(otherSide, "estimatedTime"),
            oScheduledUtc = xUtc(otherSide, "scheduledTime"),
            oQuality = xQ(otherSide)
        )
    }

    private fun String?.b(): String? = this?.takeIf { it.isNotBlank() }

    private fun xQ(mv: JSONObject?): List<String> {
        val out = ArrayList<String>()
        mv?.optJSONArray("quality")?.let { a ->
            for (i in 0 until a.length()) out.add(a.optString(i))
        }
        return out
    }

    private fun xUtc(mv: JSONObject?, k: String): String? {
        if (mv == null) return null
        val node = mv.optJSONObject(k)
        if (node != null) {
            val u = node.optString("utc").ifBlank { node.optString("Utc") }
            if (u.isNotBlank()) return u
        }
        return mv.optString(k).takeIf { it.isNotBlank() }
    }

    private fun realAt(runway: String?, actual: String?, revised: String?, sched: String?, q: List<String>): String? {
        TimeFmt.parseUtc(runway)?.let { return TimeFmt.hhmm(runway) }
        TimeFmt.parseUtc(actual)?.let { return TimeFmt.hhmm(actual) }
        val live = q.any { it.equals("live", true) }
        val rev = TimeFmt.parseUtc(revised) ?: return null
        if (live) return TimeFmt.hhmm(revised)
        val sc = TimeFmt.parseUtc(sched)
        if (sc != null && rev != sc) return TimeFmt.hhmm(revised)
        return null
    }

