            setTypeface(null, android.graphics.Typeface.BOLD)
            gravity = Gravity.CENTER
            setPadding(dp(20), dp(12), dp(20), dp(4))
        }

        fun srcIdFor(i: Int): String = srcIds.getOrElse(i) { Sources.AERODATABOX }

        fun syncVisibility() {
            val id = srcIdFor(spin.selectedItemPosition)
            boxKey.visibility = if (id == Sources.AERODATABOX) View.VISIBLE else View.GONE
            stackKey.visibility = if (id == Sources.AVIATIONSTACK) View.VISIBLE else View.GONE
            awareKey.visibility = if (id == Sources.FLIGHTAWARE) View.VISIBLE else View.GONE
            openskyNote.visibility = if (id == Sources.OPENSKY) View.VISIBLE else View.GONE
            testBtn.text = getString(R.string.test_key)
            testBtn.setTextColor(getColor(R.color.accent))
        }
        syncVisibility()
        spin.onItemSelectedListener = object : android.widget.AdapterView.OnItemSelectedListener {
