                store.setKeyFor(Sources.AVIATIONSTACK, stackKey.text.toString())
                store.setKeyFor(Sources.FLIGHTAWARE, awareKey.text.toString())
                store.setActiveSource(srcIdFor(spin.selectedItemPosition))
                refresh(silent = false)
            }
            .setNegativeButton(R.string.cancel, null)
            .show()

        testBtn.setOnClickListener {
            val srcId = srcIdFor(spin.selectedItemPosition)
