                Sources.AVIATIONSTACK -> stackKey.text.toString().trim()
                Sources.FLIGHTAWARE -> awareKey.text.toString().trim()
                else -> boxKey.text.toString().trim()
            }
            if (Sources.needsKey(srcId) && key.isBlank()) {
                Toast.makeText(this, "Enter a key first", Toast.LENGTH_SHORT).show()
                return@setOnClickListener
            }
            testBtn.text = "Testing…"
            testBtn.isEnabled = false
            scope.launch(Dispatchers.IO) {
                val msg = try {
                    val onCall: (Map<String, String>) -> Unit = { h ->
                        quota.recordHeaders(srcId, h)
                        quota.recordCall(srcId)
                        runOnUiThread { updateQuota() }
                    }
                    val s = when (srcId) {
                        Sources.AVIATIONSTACK -> AviationstackSource(key, onCall)
                        Sources.FLIGHTAWARE -> FlightAwareSource(key, onCall)
                        Sources.OPENSKY -> OpenSkySource(onCall)
                        else -> AeroDataBoxSource(key, onCall)
                    }
                    s.test()
                } catch (e: ApiException) {
                    "FAILED — HTTP ${e.code}: ${e.message?.take(60)}"
                } catch (e: Exception) {
                    "FAILED — network error"
                }
                launch(Dispatchers.Main) {
                    testBtn.isEnabled = true
                    testBtn.text = msg
                    testBtn.setTextColor(
                        getColor(if (msg.contains("OK")) R.color.arrived else R.color.error)
                    )
                    setApiStatus(msg.contains("OK"), "${Sources.label(srcId)}: ${msg.take(70)}")
                }
            }
        }
    }

